<script setup>
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';import {echarts} from '../../config/echarts';import {formatCurrency,formatCurrencyCompact} from '../../utils/chartTransforms'
const props=defineProps({data:{type:Array,default:()=>[]},unit:String,theme:{type:String,default:'shop'}})
const el=ref();let chart
const palettes={shop:['#3451b2','#2ec5ce'],user:['#6e56cf','#d864d8'],goods:['#8e4ec6','#d864d8']}
const option=computed(()=>{const rows=[...props.data].reverse(),colors=palettes[props.theme]||palettes.shop,isMoney=(props.unit||'').includes('元');return{animation:false,grid:{left:16,right:64,top:8,bottom:8,containLabel:true},tooltip:{trigger:'axis',appendToBody:true,axisPointer:{type:'shadow'},formatter:p=>`${p[0].name}<br>${isMoney?formatCurrency(p[0].value):`${Number(p[0].value).toLocaleString()}${props.unit||''}`}`},xAxis:{type:'value',show:false},yAxis:{type:'category',data:rows.map(x=>x.name),axisLabel:{interval:0,hideOverlap:false,width:126,overflow:'truncate',fontSize:11}},series:[{type:'bar',barMaxWidth:10,data:rows.map(x=>x.value),showBackground:true,backgroundStyle:{color:'rgba(111,125,153,.08)'},itemStyle:{borderRadius:6,color:new echarts.graphic.LinearGradient(0,0,1,0,[{offset:0,color:colors[0]},{offset:1,color:colors[1]}])},label:{show:true,position:'right',distance:6,color:'#d7e2f7',fontSize:11,formatter:p=>isMoney?formatCurrencyCompact(p.value):Number(p.value).toLocaleString()}}]}})
const render=()=>chart?.setOption(option.value,true);onMounted(()=>{chart=echarts.init(el.value,'warehouse');render();addEventListener('resize',render)});watch(option,render,{deep:true});onBeforeUnmount(()=>{removeEventListener('resize',render);chart?.dispose()})
</script><template><div ref="el" class="chart rank" role="img" aria-label="排行榜"></div></template>
